function [best_params, results_tbl, sweep_stats] = cor_dim_sweep(folder_path, m_max, tau, do_plot)
% COR_DIM_SWEEP Calibrates cor_dim_v2 classification thresholds across all
% labeled .mat signals in a folder generated by generate_labeled_signals.m.
%
% Usage:
%   [best_params, results_tbl, sweep_stats] = cor_dim_sweep('labeled_signals', 10, 'auto', true)
%
% Inputs:
%   folder_path - Folder containing DET_*.mat and RND_*.mat files [default: 'labeled_signals']
%   m_max       - Maximum embedding dimension (>= 6)               [default: 10]
%   tau         - Time delay (integer) or 'auto'                   [default: 'auto']
%   do_plot     - Show diagnostic threshold & distribution plots   [default: true]
%
% Outputs:
%   best_params - Struct with optimized thresholds and accuracy metrics
%   results_tbl - Per-file table of extracted D2 features and predictions
%   sweep_stats - Struct with full threshold sweep curves and confusion matrices

if nargin < 1 || isempty(folder_path), folder_path = 'labeled_signals'; end
if nargin < 2 || isempty(m_max),       m_max = 10; end
if nargin < 3 || isempty(tau),         tau = 'auto'; end
if nargin < 4 || isempty(do_plot),     do_plot = true; end

if m_max < 6
    error('m_max must be at least 6 (recommend 9 or 10).');
end
if ~exist(folder_path, 'dir')
    error('Folder "%s" does not exist.', folder_path);
end

files = dir(fullfile(folder_path, '*.mat'));
if isempty(files)
    error('No .mat files found in "%s".', folder_path);
end

n_files = numel(files);
fprintf('Extracting D2 features for %d signals in "%s" (m_max = %d)...\n', ...
    n_files, folder_path, m_max);

% Preallocate storage
FileName        = cell(n_files, 1);
TrueBinaryLabel = cell(n_files, 1);
TrueSubClass    = cell(n_files, 1);
SignalType      = cell(n_files, 1);
TauUsed         = nan(n_files, 1);
TailSlope       = nan(n_files, 1);
D2_Sat          = nan(n_files, 1);
D2_Curves       = cell(n_files, 1);

% 1. Extract correlation dimension features once per signal
for i = 1:n_files
    fname = files(i).name;
    FileName{i} = fname;

    % Parse filename format from generate_labeled_signals: <DET|RND>_<type>_rXX.mat
    tok = regexp(fname, '^(DET|RND)_(.+)_r\d+\.mat$', 'tokens', 'once');
    if ~isempty(tok)
        prefix = tok{1};
        sig_type = tok{2};
    elseif startsWith(fname, 'DET_')
        prefix = 'DET';
        sig_type = erase(fname(5:end), '.mat');
    elseif startsWith(fname, 'RND_')
        prefix = 'RND';
        sig_type = erase(fname(5:end), '.mat');
    else
        error('File "%s" does not follow DET_* or RND_* naming convention.', fname);
    end

    SignalType{i} = sig_type;
    if strcmp(prefix, 'DET')
        TrueBinaryLabel{i} = 'Deterministic';
        TrueSubClass{i}    = map_det_subclass(sig_type);
    else
        TrueBinaryLabel{i} = 'Random/Noisy';
        TrueSubClass{i}    = 'Random / Stochastic Noise';
    end

    % Load signal variable 'x'
    data = load(fullfile(folder_path, fname));
    if isfield(data, 'x')
        x = data.x;
    else
        fnames = fieldnames(data);
        x = data.(fnames{1});
    end

    % Compute D2 curve and tail features using exact cor_dim_v2 logic
    [D2_vals, tau_i, tail_slope_i, d2_sat_i] = extract_d2_features(x, m_max, tau);
    TauUsed(i)   = tau_i;
    TailSlope(i) = tail_slope_i;
    D2_Sat(i)    = d2_sat_i;
    D2_Curves{i} = D2_vals;
end

is_det_true = strcmp(TrueBinaryLabel, 'Deterministic');
is_rnd_true = ~is_det_true;
valid_mask  = ~isnan(TailSlope) & ~isnan(D2_Sat);

% 2. Stage 1 Sweep: Optimize saturation_slope_thresh (Deterministic vs Random)
valid_slopes = sort(unique(TailSlope(valid_mask)));
if numel(valid_slopes) > 1
    midpoints = 0.5 * (valid_slopes(1:end-1) + valid_slopes(2:end));
    slope_grid = unique([valid_slopes(1) - 1e-4; midpoints(:); valid_slopes(end) + 1e-4; ...
                         linspace(0.005, 0.35, 350)']);
else
    slope_grid = linspace(0.01, 0.25, 250)';
end

n_s = numel(slope_grid);
bin_acc_curve = zeros(n_s, 1);
bal_acc_curve = zeros(n_s, 1);
det_tpr_curve = zeros(n_s, 1);
rnd_tnr_curve = zeros(n_s, 1);

for k = 1:n_s
    th = slope_grid(k);
    pred_det = valid_mask & (TailSlope <= th);
    pred_rnd = valid_mask & (TailSlope > th);

    tpr = sum(pred_det & is_det_true) / max(1, sum(is_det_true));
    tnr = sum(pred_rnd & is_rnd_true) / max(1, sum(is_rnd_true));

    det_tpr_curve(k) = tpr;
    rnd_tnr_curve(k) = tnr;
    bal_acc_curve(k) = 0.5 * (tpr + tnr);
    bin_acc_curve(k) = sum((pred_det & is_det_true) | (pred_rnd & is_rnd_true)) / n_files;
end

% Maximize balanced accuracy (handles 2:1 DET/RND ratio), tie-break by overall accuracy,
% and pick the center of the optimal plateau for maximum generalization margin.
best_bal = max(bal_acc_curve);
cand_idx = find(abs(bal_acc_curve - best_bal) < 1e-12);
best_overall_on_cand = max(bin_acc_curve(cand_idx));
cand_idx = cand_idx(abs(bin_acc_curve(cand_idx) - best_overall_on_cand) < 1e-12);
opt_slope_idx = cand_idx(ceil(numel(cand_idx) / 2));
opt_slope_thresh = slope_grid(opt_slope_idx);

% 3. Stage 2 Sweep: Optimize integer_tol on saturated signals
% Evaluates both strict integer band |D2_sat - round(D2_sat)| <= tol (catching sub-1D fractals
% like logistic_map) AND legacy cor_dim_v2 rule (D2_sat <= 1 + tol).
tol_grid = linspace(0.005, 0.30, 300)';
n_t = numel(tol_grid);
sub_acc_strict = zeros(n_t, 1);
sub_acc_legacy = zeros(n_t, 1);

for k = 1:n_t
    tol = tol_grid(k);
    [~, preds_strict] = classify_with_params(TailSlope, D2_Sat, opt_slope_thresh, tol, true);
    [~, preds_legacy] = classify_with_params(TailSlope, D2_Sat, opt_slope_thresh, tol, false);

    sub_acc_strict(k) = mean(strcmp(preds_strict, TrueSubClass));
    sub_acc_legacy(k) = mean(strcmp(preds_legacy, TrueSubClass));
end

[best_sub_strict, ~] = max(sub_acc_strict);
[best_sub_legacy, ~] = max(sub_acc_legacy);

if best_sub_strict >= best_sub_legacy
    use_lower_bound_1d = true;
    sub_acc_curve = sub_acc_strict;
    best_sub_acc = best_sub_strict;
else
    use_lower_bound_1d = false;
    sub_acc_curve = sub_acc_legacy;
    best_sub_acc = best_sub_legacy;
end

tol_cand = find(abs(sub_acc_curve - best_sub_acc) < 1e-12);
opt_tol_idx = tol_cand(ceil(numel(tol_cand) / 2));
opt_integer_tol = tol_grid(opt_tol_idx);

% 4. Final Predictions & Metrics
[PredBinaryLabel, PredSubClass] = classify_with_params( ...
    TailSlope, D2_Sat, opt_slope_thresh, opt_integer_tol, use_lower_bound_1d);

IsBinaryCorrect   = strcmp(PredBinaryLabel, TrueBinaryLabel);
IsSubClassCorrect = strcmp(PredSubClass, TrueSubClass);

results_tbl = table(FileName, TrueBinaryLabel, TrueSubClass, SignalType, ...
    TauUsed, TailSlope, D2_Sat, D2_Curves, ...
    PredBinaryLabel, PredSubClass, IsBinaryCorrect, IsSubClassCorrect);

best_params = struct();
best_params.saturation_slope_thresh = opt_slope_thresh;
best_params.integer_tol             = opt_integer_tol;
best_params.use_lower_bound_1d      = use_lower_bound_1d;
best_params.m_max                   = m_max;
best_params.tau                     = tau;
best_params.binary_accuracy         = mean(IsBinaryCorrect);
best_params.balanced_accuracy       = bal_acc_curve(opt_slope_idx);
best_params.det_recall              = det_tpr_curve(opt_slope_idx);
best_params.rnd_specificity         = rnd_tnr_curve(opt_slope_idx);
best_params.multiclass_accuracy     = best_sub_acc;

class_names = {
    'Deterministic Regular (1D Periodic / Trend)'
    'Deterministic Regular (Quasi-periodic)'
    'Chaotic (Deterministic Chaos)'
    'Random / Stochastic Noise'
    };
conf_mat = compute_confusion(TrueSubClass, PredSubClass, class_names);

sweep_stats = struct();
sweep_stats.slope_grid      = slope_grid;
sweep_stats.bin_acc_curve   = bin_acc_curve;
sweep_stats.bal_acc_curve   = bal_acc_curve;
sweep_stats.det_tpr_curve   = det_tpr_curve;
sweep_stats.rnd_tnr_curve   = rnd_tnr_curve;
sweep_stats.tol_grid        = tol_grid;
sweep_stats.sub_acc_strict  = sub_acc_strict;
sweep_stats.sub_acc_legacy  = sub_acc_legacy;
sweep_stats.class_names     = class_names;
sweep_stats.confusion_mat   = conf_mat;

% 5. Command Window Report
fprintf('\n==================== COR_DIM_V2 THRESHOLD CALIBRATION ====================\n');
fprintf('Optimal saturation_slope_thresh : %.5f  (was 0.05000)\n', opt_slope_thresh);
fprintf('Optimal integer_tol             : %.5f  (was 0.10000)\n', opt_integer_tol);
fprintf('1D Lower-Bound Guard (|D2-1|)   : %d\n', use_lower_bound_1d);
fprintf('--------------------------------------------------------------------------\n');
fprintf('Binary Accuracy (DET vs RND)    : %.2f%% (%d/%d)\n', ...
    100 * best_params.binary_accuracy, sum(IsBinaryCorrect), n_files);
fprintf('Balanced Accuracy               : %.2f%% (DET Recall: %.1f%%, RND Spec: %.1f%%)\n', ...
    100 * best_params.balanced_accuracy, 100 * best_params.det_recall, 100 * best_params.rnd_specificity);
fprintf('4-Class Accuracy                : %.2f%% (%d/%d)\n', ...
    100 * best_params.multiclass_accuracy, sum(IsSubClassCorrect), n_files);
fprintf('--------------------------------------------------------------------------\n');
fprintf('Per-Signal-Type Breakdown:\n');
unique_types = unique(SignalType, 'stable');
for t = 1:numel(unique_types)
    st = unique_types{t};
    idx_t = strcmp(SignalType, st);
    fprintf('  %-18s | mean slope = %+.4f | mean D2_sat = %5.2f | BinAcc = %3.0f%% | SubAcc = %3.0f%%\n', ...
        st, mean(TailSlope(idx_t), 'omitnan'), mean(D2_Sat(idx_t), 'omitnan'), ...
        100 * mean(IsBinaryCorrect(idx_t)), 100 * mean(IsSubClassCorrect(idx_t)));
end
fprintf('==========================================================================\n\n');

% 6. Optional Diagnostic Figure
if do_plot
    plot_sweep_diagnostics(results_tbl, best_params, sweep_stats);
end
end

%% ========================================================================
%  LOCAL HELPER FUNCTIONS
%  ========================================================================
function subclass = map_det_subclass(sig_type)
switch lower(sig_type)
    case {'linear', 'quadratic', 'polynomial', 'exponential', 'sinusoid', 'sawtooth', 'chirp'}
        subclass = 'Deterministic Regular (1D Periodic / Trend)';
    case {'two_tone'}
        subclass = 'Deterministic Regular (Quasi-periodic)';
    case {'logistic_map', 'henon_map', 'lorenz_x', 'rossler_x'}
        subclass = 'Chaotic (Deterministic Chaos)';
    otherwise
        subclass = 'Chaotic (Deterministic Chaos)';
end
end

function [D2_vals, tau, tail_slope, D2_sat] = extract_d2_features(x, m_max, tau_in)
% Headless, fast implementation of cor_dim_v2 feature extraction
x = double(x(:));
x = x(~isnan(x));
N = length(x);

s = std(x);
if s == 0
    D2_vals = nan(1, m_max - 1);
    tau = 1;
    tail_slope = NaN;
    D2_sat = NaN;
    return;
end
x = (x - mean(x)) / s;

if ischar(tau_in) || isstring(tau_in) || isempty(tau_in)
    acf = xcorr(x, 'coeff');
    acf = acf(N:end);
    zero_cross = find(acf <= 0, 1, 'first');
    if isempty(zero_cross)
        tau = 1;
    else
        tau = max(1, zero_cross - 1);
    end
    max_allowed_tau = max(1, floor((N - 50) / (2 * (m_max - 1))));
    tau = min(tau, max_allowed_tau);
else
    tau = tau_in;
end

if N - (m_max - 1) * tau < 20
    error('Time series too short for specified m_max and tau.');
end

theiler_W = max(1, tau);
m_vals = 2:m_max;
num_m = length(m_vals);
D2_vals = nan(1, num_m);

for idx = 1:num_m
    m = m_vals(idx);
    N_m = N - (m - 1) * tau;
    X = zeros(N_m, m);
    for j = 1:m
        X(:, j) = x(1 + (j - 1) * tau : N_m + (j - 1) * tau);
    end

    D = pdist(X, 'euclidean');
    [row, col] = find(tril(true(N_m), -1));
    D = D((row - col) > theiler_W);
    D = D(D > 0);

    if isempty(D)
        continue;
    end

    r = logspace(log10(min(D)), log10(max(D)), 60);
    total_pairs = length(D);

    % Equivalent to arrayfun(@(rad) sum(D <= rad)/total_pairs, r) in a single O(|D|) pass
    counts = histcounts(D, [-inf, r]);
    Cr = cumsum(counts) / total_pairs;

    valid = Cr > 0;
    log_r = log(r(valid));
    log_Cr = log(Cr(valid));

    scale_idx = find(Cr(valid) >= 0.005 & Cr(valid) <= 0.25);
    if length(scale_idx) < 5
        i1 = max(1, floor(length(log_r) * 0.3));
        i2 = min(length(log_r), floor(length(log_r) * 0.7));
        scale_idx = i1:i2;
    end

    if length(scale_idx) >= 2
        p = polyfit(log_r(scale_idx), log_Cr(scale_idx), 1);
        D2_vals(idx) = p(1);
    end
end

tail_m = m_vals(end-2:end);
tail_D2 = D2_vals(end-2:end);
if any(isnan(tail_D2))
    tail_slope = NaN;
    D2_sat = NaN;
else
    slope_fit = polyfit(tail_m, tail_D2, 1);
    tail_slope = slope_fit(1);
    D2_sat = D2_vals(end);
end
end

function [bin_preds, sub_preds] = classify_with_params(tail_slope, d2_sat, slope_thresh, int_tol, strict_1d)
n = numel(tail_slope);
bin_preds = cell(n, 1);
sub_preds = cell(n, 1);

for i = 1:n
    if isnan(tail_slope(i)) || isnan(d2_sat(i))
        bin_preds{i} = 'Inconclusive';
        sub_preds{i} = 'Inconclusive';
    elseif tail_slope(i) > slope_thresh
        bin_preds{i} = 'Random/Noisy';
        sub_preds{i} = 'Random / Stochastic Noise';
    else
        bin_preds{i} = 'Deterministic';
        if strict_1d
            is_1d = abs(d2_sat(i) - 1) <= int_tol;
        else
            is_1d = d2_sat(i) <= (1 + int_tol);
        end

        if is_1d
            sub_preds{i} = 'Deterministic Regular (1D Periodic / Trend)';
        elseif round(d2_sat(i)) >= 2 && abs(d2_sat(i) - round(d2_sat(i))) <= int_tol
            sub_preds{i} = 'Deterministic Regular (Quasi-periodic)';
        else
            sub_preds{i} = 'Chaotic (Deterministic Chaos)';
        end
    end
end
end

function cm = compute_confusion(y_true, y_pred, labels)
K = numel(labels);
cm = zeros(K, K);
for r = 1:K
    for c = 1:K
        cm(r, c) = sum(strcmp(y_true, labels{r}) & strcmp(y_pred, labels{c}));
    end
end
end

function plot_sweep_diagnostics(results_tbl, best_params, sweep_stats)
figure('Position', [80, 80, 1250, 750], 'Name', 'cor_dim_v2 Threshold Calibration');

% 1. Slope Threshold Sweep Curve
subplot(2, 2, 1);
plot(sweep_stats.slope_grid, 100 * sweep_stats.bal_acc_curve, 'b-', 'LineWidth', 1.8, 'DisplayName', 'Balanced Acc');
hold on;
plot(sweep_stats.slope_grid, 100 * sweep_stats.bin_acc_curve, 'k--', 'LineWidth', 1.4, 'DisplayName', 'Overall Binary Acc');
xline(best_params.saturation_slope_thresh, 'r-', 'LineWidth', 1.8, ...
    'DisplayName', sprintf('Optimal = %.4f', best_params.saturation_slope_thresh));
xlabel('saturation\_slope\_thresh');
ylabel('Accuracy (%)');
title('Stage 1: Slope Threshold Sweep (DET vs RND)');
legend('Location', 'best');
grid on; hold off;

% 2. Integer Tolerance Sweep Curve
subplot(2, 2, 2);
plot(sweep_stats.tol_grid, 100 * sweep_stats.sub_acc_strict, 'g-', 'LineWidth', 1.8, 'DisplayName', 'With |D2 - 1| <= tol');
hold on;
plot(sweep_stats.tol_grid, 100 * sweep_stats.sub_acc_legacy, 'm--', 'LineWidth', 1.4, 'DisplayName', 'Legacy D2 <= 1 + tol');
xline(best_params.integer_tol, 'r-', 'LineWidth', 1.8, ...
    'DisplayName', sprintf('Optimal = %.4f', best_params.integer_tol));
xlabel('integer\_tol');
ylabel('4-Class Accuracy (%)');
title('Stage 2: Integer Tolerance Sweep');
legend('Location', 'best');
grid on; hold off;

% 3. Feature Space Scatter (Tail Slope vs D2_sat)
subplot(2, 2, 3);
classes = sweep_stats.class_names;
markers = {'o', 's', '^', 'x'};
colors  = [0.1 0.5 0.8; 0.2 0.7 0.3; 0.9 0.5 0.1; 0.8 0.1 0.1];
hold on;
for c = 1:numel(classes)
    idx = strcmp(results_tbl.TrueSubClass, classes{c});
    scatter(results_tbl.TailSlope(idx), results_tbl.D2_Sat(idx), 55, colors(c, :), markers{c}, ...
        'LineWidth', 1.5, 'DisplayName', classes{c});
end
xline(best_params.saturation_slope_thresh, 'k--', 'LineWidth', 1.5, 'DisplayName', 'Slope Threshold');
xlabel('Tail Slope (dD_2 / dm)');
ylabel('Saturation D_2 (at m_{max})');
title('Signal Distribution & Decision Boundary');
legend('Location', 'best', 'FontSize', 7.5);
grid on; hold off;

% 4. Confusion Matrix Heatmap
subplot(2, 2, 4);
short_labels = {'1D Reg', 'Quasi-Per', 'Chaotic', 'Random'};
imagesc(sweep_stats.confusion_mat);
colormap(gca, parula);
colorbar;
set(gca, 'XTick', 1:4, 'XTickLabel', short_labels, 'YTick', 1:4, 'YTickLabel', short_labels);
xlabel('Predicted Class');
ylabel('True Class');
title(sprintf('4-Class Confusion Matrix (Acc = %.1f%%)', 100 * best_params.multiclass_accuracy));
for r = 1:4
    for c = 1:4
        text(c, r, num2str(sweep_stats.confusion_mat(r, c)), ...
            'HorizontalAlignment', 'center', 'Color', 'w', 'FontWeight', 'bold', 'FontSize', 11);
    end
end
end